'use client'
import React, { useEffect, useState } from 'react';
import AliceCarousel from 'react-alice-carousel';
import axios from 'axios';
import styles from './Slider_fav.module.css';
import "react-alice-carousel/lib/alice-carousel.css";

import { FaArrowLeft } from "react-icons/fa";
import { FaArrowRight } from "react-icons/fa";

const Slider_fav = () => {
  const [movies, setMovies] = useState([]);
  const [loading, setLoading] = useState(true);

  const renderNextButton = ({ isDisabled }) => {
    return <FaArrowRight size={20} color='#11100F' className={styles.next_btn}/>;
  };
  const renderPrevButton = ({ isDisabled }) => {
    return <FaArrowLeft size={20} color='#11100F' className={styles.prev_btn}/>;
  };

  const responsive = {
    400: { items: 2 },
    840: { items: 3 },
    1220: { items: 4 },
    1600: { items: 5 },
    2200: { items: 5}
  };

  // OMDb API
  useEffect(() => {
    const fetchMovies = async () => {
      try {
        const response = await axios.get('https://www.omdbapi.com/?apikey=a479eec2&s=popular&type=movie');
        setMovies(response.data.Search || []);
        setLoading(false);
      } catch (error) {
        console.error('Error fetching movies:', error);
        setLoading(false);
      }
    };

    fetchMovies();
  }, []);

  if (loading) return <div className={styles.cont_main}>Loading...</div>;

  // Слайдер с фильмами
  const movieItems = movies.map((movie) => (
    <div key={movie.imdbID} className={styles.sliderItem}>
      <img src={movie.Poster} alt={movie.Title} />
      <h4>{movie.Title}</h4>
    </div>
  ));

  return (
    <div className={styles.cont_main}>
      <div className={styles.text_fav}>
        Избранные
      </div>
      <div className={styles.movieSlider}>
        <AliceCarousel
          mouseTracking
          items={movieItems}
          responsive={responsive}
          infinite
          //autoPlay
          autoPlayInterval={3000}
          animationDuration={1000}

          disableDotsControls="true"
          controlsStrategy="alternate"
          renderPrevButton={renderPrevButton}
          renderNextButton={renderNextButton}
        />
      </div>
    </div>
    
  );
};

export default Slider_fav;
